"""Dairy, bakery, pantry catalog expansion to 100 assets per category."""
import json
from local_image_catalog_common import *

def dairy():
    milk=flavored('Flavoured Milk Bottle|ఫ్లేవర్డ్ పాల సీసా',[(en,te) for en,te in FLAVORS if en not in ['Rose','Coffee']])
    yogurt=flavored('Yogurt Cup|యోగర్ట్ కప్పు',FLAVORS)
    cheese=rows('Cheddar|చెడ్డార్;Mozzarella|మొజారెల్లా;Parmesan|పార్మెసాన్;Gouda|గౌడా;Feta|ఫెటా;Brie|బ్రీ;Camembert|కామెంబెర్ట్;Blue Cheese|బ్లూ చీజ్;Edam|ఈడమ్;Emmental|ఎమెంటల్;Swiss Cheese|స్విస్ చీజ్;Ricotta|రికోటా;Mascarpone|మస్కార్పోన్;Cream Cheese|క్రీమ్ చీజ్;Provolone|ప్రోవలోన్;Smoked Cheese|స్మోక్డ్ చీజ్;Burrata|బుర్రాటా;Halloumi|హలూమి;Goat Cheese|మేక పాల చీజ్;Cottage Cheese|కాటేజ్ చీజ్',' Cheese Portion',' చీజ్ ముక్క')
    cheese=[(en.replace('Cheese Cheese','Cheese'),te.replace('చీజ్ చీజ్','చీజ్')) for en,te in cheese]
    cultured=rows('Cow Milk Bottle|ఆవు పాల సీసా;Buffalo Milk Bottle|గేదె పాల సీసా;Goat Milk Bottle|మేక పాల సీసా;Skimmed Milk Bottle|స్కిమ్డ్ పాల సీసా;Toned Milk Pouch|టోన్డ్ పాల ప్యాకెట్;Double Toned Milk Pouch|డబుల్ టోన్డ్ పాల ప్యాకెట్;Lactose Free Milk Carton|లాక్టోస్ ఫ్రీ పాల ప్యాక్;Evaporated Milk Can|ఇవాపరేటెడ్ పాల డబ్బా;Heavy Cream Carton|హెవీ క్రీమ్ ప్యాక్;Whipping Cream Carton|విప్పింగ్ క్రీమ్ ప్యాక్;Sour Cream Tub|సవర్ క్రీమ్ డబ్బా;Clotted Cream Jar|క్లాటెడ్ క్రీమ్ సీసా;Unsalted Butter Block|ఉప్పులేని వెన్న ముక్క;Salted Butter Block|ఉప్పు వెన్న ముక్క;Cultured Butter Block|కల్చర్డ్ వెన్న ముక్క;White Butter Block|తెల్ల వెన్న ముక్క;Greek Yogurt Cup|గ్రీక్ యోగర్ట్ కప్పు;Probiotic Curd Cup|ప్రోబయోటిక్ పెరుగు కప్పు;Hung Curd Tub|గట్టి పెరుగు డబ్బా;Kefir Milk Bottle|కెఫిర్ పాల సీసా')
